Add a pin for each place you’ve been by editing the places array below — each entry just needs a name, lat/lng, and a short note.

L = require("leaflet@1.9.4")







places = [
  { name: "Example City, Country", lat: 0, lng: 0, note: "What you did there, when" }
  // add more entries here
]







{
  const container = DOM.element("div", { style: "height:420px;border-radius:6px;" });
  yield container;
  const map = L.map(container).setView([20, 0], 2);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "© OpenStreetMap contributors"
  }).addTo(map);
  places.forEach(p =&gt; {
    L.marker([p.lat, p.lng]).addTo(map).bindPopup(`&lt;b&gt;${p.name}&lt;/b&gt;&lt;br&gt;${p.note}`);
  });
}

