Live list of public repositories, pulled directly from GitHub — this page updates itself automatically as you create or update repos, no manual edits needed.

repos = {
  const res = await fetch("https://api.github.com/users/chrystali2002/repos?sort=updated&per_page=100");
  const data = await res.json();
  return data.filter(r =&gt; !r.fork).sort((a, b) =&gt; b.stargazers_count - a.stargazers_count);
}







html`${repos.map(r =&gt; `
  &lt;div class="card-block"&gt;
    &lt;h3&gt;&lt;a href="${r.html_url}" target="_blank"&gt;${r.name}&lt;/a&gt;&lt;/h3&gt;
    &lt;p&gt;${r.description ?? "No description provided."}&lt;/p&gt;
    &lt;span class="pill"&gt;${r.language ?? "—"}&lt;/span&gt;
    &lt;span class="pill"&gt;★ ${r.stargazers_count}&lt;/span&gt;
    &lt;span class="pill"&gt;Updated ${new Date(r.updated_at).toLocaleDateString()}&lt;/span&gt;
  &lt;/div&gt;
`).join("")}`






